WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) UPDATE executivos SET ativo = CAST(:ativo AS BOOLEAN) FROM eu WHERE executivos.id = CAST(:id AS INTEGER) AND eu.admin RETURNING executivos.id, executivos.ativo
